<?php require_once __DIR__.'/config.php';$u=require_login();if($_SERVER['REQUEST_METHOD']!=='POST')exit;check_csrf();$id=(int)($_POST['thread_id']??0);$msg=trim($_POST['message']??'');if($msg==='')exit('Пустой ответ.');$r=data_load('replies_'.$id.'.json');$r[]=['id'=>count($r)+1,'author'=>$u['username'],'message'=>$msg,'created_at'=>date('c')];data_save('replies_'.$id.'.json',$r);header('Location:thread.php?id='.$id);exit;